{"path": "creative_intent.json", "content": "{
  "user_need": "狂躁症男主（超忆，记得所有细节）和抑郁症女主（失忆，每天刷新）被医生配对\"互相治疗\"（实则是观察实验）。男主每天重新追求女主，女主每天重新爱上他，直到女主某天没有失忆，发现男主是故意让她依赖，因为\"只有疯子的爱情才纯粹\"。场景：精神病院。物件：病历本、药瓶。疯点：墙上刻字。单频振动：病态的纯粹。",
  "inspiration_state": "clear_inspiration",
  "extracted_elements": {
    "emotion_verbs": ["追求", "重置", "依赖", "献祭", "刻画"],
    "scene_elements": ["精神病院", "白色牢笼", "病历本", "药瓶", "刻满字的墙"],
    "relationship_tension": ["记忆与遗忘", "医生与病人", "治愈与致病", "控制与依赖"],
    "user_preferences": {
      "desired_emotion": "病态纯粹",
      "forbidden": ["庸俗的大团圆", "理智的回归"]
    }
  },
  "selected_recipe": {
    "x_axis_mode_id": "D22",
    "x_axis_mode_name": "为激情献祭",
    "y_axis_tags": ["规则怪谈", "双向暗恋", "刑侦悬疑"],
    "reaction_strength": "✷",
    "tension_stars": 5,
    "forbidden_elements": ["平庸的治愈", "外界的干扰"],
    "x_axis_display": "男主为了维持爱情的纯粹，主动阻断女主的康复，牺牲了她的理智与自由。",
    "y_axis_combination_effect": "规则怪谈的压抑环境强化了双向暗恋的吊桥效应，刑侦悬疑揭示了实验的残酷真相。",
    "reaction_formula": "D22(献祭) + 规则怪谈 = 以爱为名的囚禁实验",
    "platform_fit": ["知乎", "LOFTER", "晋江"]
  },
  "one_sentence_synopsis": "在每日重置的精神病院里，拥有超忆症的他为了留住失忆的她，精心编织了一场以爱为名的囚禁实验，直到她觉醒并甘愿沉沦。"
}"}

