        "emotional_tone": "震撼、恐怖、悲凉",
        "key_scenes": ["撕开墙纸", "阅读记录", "意识到时间的重量"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "疯子的圣所",
        "core_event": "陆妄醒来发现苏眠未失忆，崩溃欲绝；苏眠选择吞药，主动留在这个世界",
        "emotional_tone": "疯狂、极致的浪漫、毁灭性的治愈",
        "key_scenes": ["陆妄的崩溃", "苏眠的拥抱", "最后的吞药"]
      }
    ]
  }
